package cl.bolsillo.app;
import android.widget.*;import org.json.*;import java.time.*;import java.util.*;
final class PlannedScreen {
 static void screen(MainActivity a)throws Exception{String end=LocalDate.parse(Ledger.today()).withDayOfMonth(LocalDate.parse(Ledger.today()).lengthOfMonth()).toString();Modern.add(a.body,Modern.stat(a,"calendar","Previstos este mes",a.money(Finance.planned(a.data,end)),Glass.AMBER),4);Modern.section(a,"Próximos pagos","Añadir",()->edit(a,null));List<JSONObject> plans=new ArrayList<>();JSONArray list=a.data.getJSONArray("planned");for(int i=0;i<list.length();i++)plans.add(list.getJSONObject(i));plans.sort(Comparator.comparing(p->p.optString("date")));for(JSONObject p:plans)Modern.add(a.body,Modern.item(a,Modern.iconFor(p.optString("name")),p.getString("name"),p.getString("date")+" · "+(p.optString("status").equals("planned")?"Previsto":p.optString("status").equals("paid")?"Pagado":"Cancelado"),a.money(p.getLong("amount")),Glass.AMBER,()->menu(a,p)),8);Modern.section(a,"Suscripciones","Ver",()->a.navigate("Suscripciones"));JSONArray r=a.data.getJSONArray("recurring");for(int i=0;i<r.length();i++)if(r.getJSONObject(i).optBoolean("active")&&r.getJSONObject(i).optString("type").equals("expense"))Subscriptions.row(a,r.getJSONObject(i));if(list.length()==0)a.caption("Añade un pago futuro. No descuenta dinero hasta que lo registres.");}
 static void menu(MainActivity a,JSONObject p){List<String> choices=p.optString("status").equals("planned")?Arrays.asList("Registrar pago hoy","Editar previsto","Cancelar previsto"):Arrays.asList("Ver detalle");NativeSettings.choose(a,p.optString("name"),choices,n->a.attempt(()->{if(!p.optString("status").equals("planned")){NativeSettings.info(a,p.optString("date")+" · "+a.money(p.optLong("amount")));return;}if(n==0)a.confirm("Registrar pago",p.optString("name")+" · "+a.money(p.optLong("amount")),()->LocalData.change(a,d->Finance.payPlan(d,p.getString("id"))));else if(n==1)edit(a,p);else LocalData.upsert(a,"planned",new JSONObject(p.toString()).put("status","cancelled"));a.render();}));}
 static void edit(MainActivity a,JSONObject old)throws Exception{JSONObject p=old==null?new JSONObject().put("id",Ledger.id()).put("status","planned"):new JSONObject(old.toString());Forms.Form f=new Forms.Form(a,old==null?"Gasto previsto":"Editar previsto");AutoCompleteTextView name=f.conceptField("Pago",p.optString("name"),"expense");EditText amount=f.field("Monto",p.optString("amount"),true),date=f.field("Fecha prevista",p.optString("date",Ledger.today()),false);Forms.Pick account=new Forms.Pick(f,"Cuenta","accounts","",p.optString("account")),cat=new Forms.Pick(f,"Categoría","categories","expense",p.optString("category"));f.bindConcept(name,cat,"expense");f.save("Guardar previsto",()->{Ledger.require(!Forms.value(name).isEmpty(),"Escribe el pago");p.put("name",Forms.value(name)).put("amount",Forms.amount(amount,false)).put("date",LocalDate.parse(Forms.value(date)).toString()).put("account",account.id()).put("category",cat.id());LocalData.upsert(a,"planned",p);});}
}
